'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={data:null,selected:new Set(),kind:'all',query:'',page:1,perPage:15,report:null,reportTab:'issues',findingFilter:'all',evidenceQuery:'',evidenceUrl:'',reports:[],comparison:[],route:'registry',busy:false};
const kindName=k=>k==='school'?'Школа':'Детский сад';
const shortName=name=>{const m=name.match(/["«]([^"»]+)["»]/);return m?m[1]:name};
const siteCount=n=>n+' '+(n%10===1&&n%100!==11?'сайт':n%10>=2&&n%10<=4&&!(n%100>=12&&n%100<=14)?'сайта':'сайтов');
const date=(s,time=false)=>s?new Date(s).toLocaleString('ru-RU',{timeZone:'Asia/Magadan',day:'2-digit',month:'short',year:'numeric',...(time?{hour:'2-digit',minute:'2-digit'}:{})}):'—';
const statusNames={pass:'Проверено',fail:'Проблема',review:'Требует проверки',unknown:'Нет данных',queued:'В очереди',running:'Выполняется',completed:'Завершена',cancelled:'Остановлена',interrupted:'Прервана',processing:'Обрабатывается',unavailable:'Сайт недоступен',partial:'Частичный обход',complete:'Обход завершён'};
const badge=(s,label)=>`<span class="badge ${esc(s)}">${esc(label||statusNames[s]||s)}</span>`;
const pct=v=>v==null?'—':v+'%';const PRIORITY={critical:'Критичный',high:'Высокий',medium:'Средний',low:'Низкий'};const SEV={critical:0,high:1,medium:2,low:3};const modeName=m=>({quick:'Быстрый обзор',import:'Импорт результата CLI',full:'Полная проверка'})[m]||'Полная проверка';
const activeRun=()=>state.data?.runs.find(r=>['queued','running'].includes(r.status));
let toastTimer,queryTimer,polling=false;
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className='show'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.className='',error?10000:5000)}
async function api(url,options={}){let response;try{response=await fetch(url,{...options,headers:{'Content-Type':'application/json',...(state.data?{'X-Audit-Session':state.data.session}:{}),...options.headers}})}catch{throw new Error('Нет связи с приложением. Убедитесь, что сервис запущен, и повторите действие.')}if(!response.ok){let message;try{const data=await response.json();message=typeof data.detail==='string'?data.detail:JSON.stringify(data.detail)}catch{message=await response.text().catch(()=>response.statusText)}throw new Error(message||'Не удалось выполнить запрос')}return response.json()}
async function refresh(render=true){state.data=await api('/api/state');$('#nav-count').textContent=state.data.organizations.length;$('#connection-state').textContent='Движок audit · '+(state.data.settings.llm_enabled?'ИИ включён':'без ИИ');if(render&&['registry','reports'].includes(state.route)){if(state.route==='reports')state.reports=await api('/api/reports');renderView()}}
function navigate(){return location.hash.slice(1)||'registry'}
async function loadRoute(){if(!state.data)return;const hash=navigate();const parts=hash.split('/');state.route=parts[0];for(const el of document.querySelectorAll('[data-nav]'))el.classList.toggle('active',el.dataset.nav===(state.route==='report'?'reports':state.route));if(state.route==='report'){if(!state.report||state.report.id!==Number(parts[1])){state.reportTab='issues';state.findingFilter='all';state.evidenceQuery='';state.evidenceUrl='';$('#view').innerHTML='<div class="loading">Открываем отчёт…</div>';try{state.report=await api('/api/reports/'+Number(parts[1]))}catch(e){$('#view').innerHTML=`<div class="empty"><h2>Не удалось открыть отчёт</h2><p>${esc(e.message)}</p><div class="actions" style="justify-content:center"><button data-action="retry-route">Повторить</button><a class="button" href="#reports">К проверкам</a></div></div>`;return}}}else if(state.route==='reports')state.reports=await api('/api/reports');else if(state.route==='comparison')state.comparison=await api('/api/comparison');renderView();window.scrollTo({top:0,behavior:'instant'})}
function renderView(){const views={registry:registry,reports:reportsView,report:reportView,settings:settingsView,comparison:comparisonView,checklist:checklistView};$('#view').innerHTML=(views[state.route]||registry)()}
function elapsed(created){const sec=Math.max(0,Math.floor((Date.now()-new Date(created).getTime())/1000));return sec<60?sec+' с':Math.floor(sec/60)+' мин '+String(sec%60).padStart(2,'0')+' с'}
function runBanner(){const r=activeRun();if(!r)return '';const ratio=Math.round(r.done/r.total*100);const preliminary=state.data.organizations.filter(o=>o.latest?.preliminary).length;return `<div class="banner run-banner"><div class="run-status"><div class="actions"><b>Проверка в работе</b>${badge('running',`${r.done} из ${r.total} готовы`)}<span class="run-elapsed">${elapsed(r.created)}</span></div><p class="run-current">${esc(r.current||'Формируем очередь сайтов…')}</p><div class="progress ${r.done===0?'indeterminate':''}"><span style="width:${ratio}%"></span></div><div class="run-caption">${preliminary?'Уже доступны предварительные отчёты: '+preliminary+'. ':'Результаты сохраняются по мере готовности. '}Проверки audit по сайтам → сверка между сайтами запуска → итоговые отчёты.</div></div><button data-action="cancel-run" data-id="${r.id}">Остановить</button></div>`}
function registry(){const orgs=state.data.organizations;const checked=orgs.filter(o=>o.latest&&!o.latest.preliminary);const reviews=checked.reduce((s,o)=>s+o.latest.review,0);const unavailable=checked.filter(o=>o.latest.status==='unavailable').length;const schools=orgs.filter(o=>o.kind==='school').length;const filtered=orgs.filter(o=>(state.kind==='all'||o.kind===state.kind||state.kind==='unverified'&&!o.latest)&&(o.name+' '+o.url).toLowerCase().includes(state.query.toLowerCase()));const maxPage=Math.max(1,Math.ceil(filtered.length/state.perPage));state.page=Math.min(state.page,maxPage);const rows=filtered.slice((state.page-1)*state.perPage,state.page*state.perPage);const allVisible=rows.length&&rows.every(o=>state.selected.has(o.id));
return `<div class="page-heading"><div><div class="eyebrow">РЕЕСТР УЧРЕЖДЕНИЙ</div><h1>Реестр сайтов</h1><p>Содержание, актуальность и проверяемые основания.</p></div><div class="actions"><button data-action="add-org">Добавить сайт</button><button class="primary" data-action="new-run" ${activeRun()?'disabled':''}><span class="plus">→</span> Запустить проверку</button></div></div>
<div class="stats"><div class="stat"><div class="stat-label">В реестре</div><div class="stat-value">${orgs.length}</div><div class="stat-detail">${schools} школ · ${orgs.length-schools} детских садов</div></div><div class="stat"><div class="stat-label">Готовые отчёты</div><div class="stat-value">${checked.length}<span class="muted" style="font-size:16px;letter-spacing:0"> / ${orgs.length}</span></div><div class="stat-detail">${checked.length?'По последним проверкам':'Первая проверка ещё впереди'}</div></div><div class="stat"><div class="stat-label">Наблюдения</div><div class="stat-value">${checked.length?reviews:'—'}</div><div class="stat-detail">${checked.length?'Наблюдения для ручной проверки':'Появятся после проверки'}</div></div><div class="stat"><div class="stat-label">Нет доступа</div><div class="stat-value">${checked.length?unavailable:'—'}</div><div class="stat-detail">${checked.length?'Не удалось получить данные':'Данные ещё не получены'}</div></div></div>
${runBanner()}
${!checked.length&&!activeRun()?`<div class="banner"><div><b>Начните с первой проверки</b><p>Все учреждения из задания уже в реестре. Выберите несколько сайтов или проверьте весь список.</p></div><a class="button small" href="#checklist">Что проверяем <span style="margin-left:12px">→</span></a></div>`:''}
<section class="panel" aria-label="Реестр организаций"><div class="toolbar"><div class="tabs" aria-label="Тип организации">${[['all','Все организации',orgs.length],['school','Школы',schools],['kindergarten','Детские сады',orgs.length-schools]].map(([k,l,n])=>`<button data-action="kind" data-kind="${k}" class="${state.kind===k?'selected':''}" aria-pressed="${state.kind===k}">${l}<span class="count">${n}</span></button>`).join('')}</div><div class="search"><input id="registry-search" type="search" placeholder="Найти по названию или адресу" aria-label="Поиск организаций" value="${esc(state.query)}"></div></div>
${state.selected.size?`<div class="selection-bar"><span>Выбрано организаций: <b>${state.selected.size}</b></span><div class="actions"><button class="text-button small" data-action="clear-selection">Снять выбор</button><button class="primary small" data-action="new-run" ${activeRun()?'disabled':''}>Проверить выбранные</button></div></div>`:''}
<div class="mobile-caption">Таблицу можно прокрутить вправо →</div><div class="table-wrap"><table class="registry-table"><thead><tr><th><input type="checkbox" id="select-page" aria-label="Выбрать организации на этой странице" ${allVisible?'checked':''}></th><th>Организация / сайт</th><th>Тип</th><th>Проверка</th><th>Состояние</th><th></th></tr></thead><tbody>${rows.map(o=>`<tr><td><input type="checkbox" data-select="${o.id}" aria-label="Выбрать ${esc(o.name)}" ${state.selected.has(o.id)?'checked':''}></td><td><button class="org-name" data-action="open-org" data-id="${o.id}" aria-label="${esc(o.name)}"><span class="org-index">${String(o.id).padStart(2,'0')}</span>${esc(shortName(o.name))}</button><span class="org-formal" title="${esc(o.name)}">${esc(o.name)}</span><a class="org-url" href="${esc(o.url)}" target="_blank" rel="noopener noreferrer">${esc(new URL(o.url).hostname)} ↗</a>${o.latest?`<a class="mobile-report" href="#report/${o.latest.id}">Открыть отчёт →</a>`:''}</td><td><span class="type"><i aria-hidden="true">${o.kind==='school'?'▥':'▧'}</i>${kindName(o.kind)}</span></td><td class="numeric nowrap">${o.latest?date(o.latest.created):'<span class="no-data">Ещё не проверялся</span>'}</td><td>${!o.latest?badge('unknown','Не проверено'):o.latest.preliminary?badge('running','Отчёт формируется'):o.latest.status==='unavailable'?badge('unknown','Нет доступа'):o.latest.issues?badge('fail',o.latest.issues+' проблем'+(o.latest.critical?' · '+o.latest.critical+' критичных':'')):o.latest.review?badge('review',o.latest.review+' к проверке'):badge('pass','Отчёт получен')}${o.latest&&o.latest.status!=='unavailable'?`<div class="state-info">Охват ${pct(o.latest.coverage)} · ${o.latest.pages} стр.${o.latest.audit_score!=null?' · балл audit '+o.latest.audit_score:''}</div>`:''}</td><td>${o.latest?`<a class="button small" href="#report/${o.latest.id}">Отчёт →</a>`:`<button class="text-button small" data-action="run-one" data-id="${o.id}" ${activeRun()?'disabled':''}>Проверить →</button>`}</td></tr>`).join('')||'<tr><td colspan="6"><div class="empty"><h2>Организации не найдены</h2><p>Попробуйте другое название или адрес сайта.</p></div></td></tr>'}</tbody></table></div>
<div class="table-bottom"><span>${filtered.length?`${(state.page-1)*state.perPage+1}–${Math.min(state.page*state.perPage,filtered.length)} из ${filtered.length} организаций`:'Ничего не найдено'}</span><div class="pagination"><button data-action="prev-page" ${state.page===1?'disabled':''} aria-label="Предыдущая страница">←</button><span>${state.page} / ${maxPage}</span><button data-action="next-page" ${state.page===maxPage?'disabled':''} aria-label="Следующая страница">→</button></div></div></section><div class="help-line"><span>Реестр загружен из материалов кейса. Можно добавить свой сайт.</span><a href="/api/export/summary.csv">Скачать сводную таблицу ↓</a></div>`}
function reportsView(){return `<div class="page-heading"><div><div class="eyebrow">ЖУРНАЛ МОНИТОРИНГА</div><h1>Проверки и отчёты</h1><p>История запусков и сохранённые результаты по каждому сайту.</p></div><button class="primary" data-action="new-run" ${activeRun()?'disabled':''}>Новая проверка</button></div>${runBanner()}${!state.data.runs.length?`<div class="panel empty"><div class="empty-symbol" aria-hidden="true">≡</div><h2>Проверки ещё не запускались</h2><p>Начните с нескольких организаций. По каждой появится отдельный отчёт со ссылками, доказательствами и приоритетом исправлений.</p><button class="primary" data-action="new-run">Выбрать сайты для проверки</button></div>`:`<section class="panel"><div class="toolbar"><h2 style="margin:0;font-size:16px">Последние запуски</h2><span class="muted small">Время Магадана · UTC+11</span></div>${state.data.runs.slice(0,8).map(r=>`<div class="toolbar"><div><div class="run-row-title">${date(r.created,true)} <span class="muted">·</span> ${siteCount(r.total)}</div><div class="timeline">${modeName(r.mode)} · Готово ${r.done} из ${r.total} ${r.finished?'· Завершение '+date(r.finished,true):''}</div>${r.outputs?`<div class="state-info">Выгрузки audit: <a href="/runs/${esc(r.id)}/index.html" target="_blank" rel="noopener">HTML-отчёт ↗</a> · <a href="/runs/${esc(r.id)}/summary.xlsx">XLSX ↓</a> · <a href="/runs/${esc(r.id)}/findings.csv">CSV ↓</a> · <a href="/runs/${esc(r.id)}/results.json">results.json ↓</a></div>`:''}${r.error?`<p class="state-info">${esc(r.error)}</p>`:''}</div>${badge(r.status)}</div>`).join('')}</section><div class="section-heading"><h2>Отчёты по организациям</h2><a href="/api/export/summary.csv">Сводная таблица ↓</a></div><div class="panel table-wrap"><table><thead><tr><th>Организация</th><th>Дата</th><th>Охват</th><th>Выводы</th><th></th></tr></thead><tbody>${state.reports.map(r=>`<tr><td><a href="#report/${r.id}" class="org-name">${esc(r.name)}</a></td><td class="nowrap">${date(r.created,true)}</td><td>${pct(r.coverage)}</td><td>${r.status==='unavailable'?badge('unknown','Нет доступа'):badge(r.issues?'fail':'review',`${r.issues} проблем · ${r.review} к проверке`)}</td><td><a class="button small" href="#report/${r.id}">Открыть →</a></td></tr>`).join('')||'<tr><td colspan="5"><div class="empty">Готовые отчёты появятся здесь по мере проверки сайтов.</div></td></tr>'}</tbody></table></div>`}`}
function finding(c){const mark=state.report.reviews[c.fingerprint]||{state:'open',note:''};return `<article class="finding ${c.status}"><div class="finding-header"><span class="eyebrow">${esc(c.section)} ${({llm:'· АНАЛИЗ МОДЕЛИ',crossval:'· СВЕРКА МЕЖДУ САЙТАМИ',manual:'· РУЧНАЯ ПРОВЕРКА'})[c.method]||''}</span><div class="actions">${badge(c.status)}<span class="state-info">${PRIORITY[c.severity]} приоритет</span></div></div><h3>${esc(c.title)}</h3><div class="eyebrow">ОСНОВАНИЕ</div><blockquote style="white-space:pre-line">${esc(c.evidence||'Достаточных данных не получено.')}</blockquote><div class="recommendation"><b>Что сделать.</b> ${esc(c.recommendation)}</div>${c.reason?`<p class="state-info">${esc(c.reason)}</p>`:''}<div class="finding-links">${state.report.data.pages.some(p=>p.url.replace(/\/$/,'')===c.url.replace(/\/$/,''))?`<button class="text-button small" style="padding:0;min-height:0;font-weight:400;text-decoration:underline" data-action="saved-source" data-url="${esc(c.url)}">Сохранённый текст</button>`:''}<a href="${esc(c.url)}" target="_blank" rel="noopener noreferrer">Открыть страницу ↗</a>${c.related_url?`<a href="${esc(c.related_url)}" target="_blank" rel="noopener noreferrer">Сравнить со второй страницей ↗</a>`:''}${c.source_url?`<a href="${esc(c.source_url)}" target="_blank" rel="noopener noreferrer">Внешний источник ↗</a>`:''}</div>${c.source_quote?`<blockquote>${esc(c.source_quote)}</blockquote>`:''}${c.status!=='pass'?`<div class="review-controls" data-fingerprint="${esc(c.fingerprint)}"><label>Решение инспектора</label><select aria-label="Статус замечания"><option value="open" ${mark.state==='open'?'selected':''}>Открыто</option><option value="confirmed" ${mark.state==='confirmed'?'selected':''}>Подтверждено</option><option value="dismissed" ${mark.state==='dismissed'?'selected':''}>Не подтвердилось</option><option value="fixed" ${mark.state==='fixed'?'selected':''}>Исправлено</option></select><input aria-label="Комментарий инспектора" placeholder="Комментарий" value="${esc(mark.note)}" maxlength="2000"><button class="small" data-action="save-review">Сохранить</button></div>`:''}</article>`}
function reportView(){const r=state.report;if(!r)return '';const d=r.data;const counts={};for(const c of d.checks)counts[c.status]=(counts[c.status]||0)+1;let content='';const sort=a=>[...a].sort((a,b)=>SEV[a.severity]-SEV[b.severity]);if(state.reportTab==='issues'){const list=sort(d.checks.filter(c=>['fail','review'].includes(c.status)&&(state.findingFilter==='all'||c.severity===state.findingFilter)));content=`<div class="section-heading"><h2>В первую очередь</h2><select id="finding-filter" class="filter-select" aria-label="Фильтр приоритета">${[['all','Все приоритеты'],['critical','Критичный'],['high','Высокий'],['medium','Средний'],['low','Низкий']].map(([v,t])=>`<option value="${v}" ${state.findingFilter===v?'selected':''}>${t}</option>`).join('')}</select></div><div class="findings">${list.map(finding).join('')||'<div class="info-panel"><h3>Подтверждённых проблем не найдено</h3><p>Проверьте охват и вкладку «Нет данных». Отсутствие замечаний не означает, что все требования соблюдены.</p></div>'}</div>`}else if(state.reportTab==='unknown'){content=`<h2>Для этих выводов не хватило данных</h2><p class="muted">Они не учтены как нарушения и не повышают оценку.</p><div class="findings">${d.checks.filter(c=>c.status==='unknown').map(finding).join('')||'<div class="info-panel">Пункты без данных отсутствуют.</div>'}</div>`}else if(state.reportTab==='passed'){content=`<div class="findings">${d.checks.filter(c=>c.status==='pass').map(finding).join('')||'<div class="info-panel">Пока нет подтверждённых проверок.</div>'}</div>`}else if(state.reportTab==='documents'){content=`<h2>Перечень найденных документов</h2><p class="muted">Найдено ${d.documents.length} документов. Движок audit распознаёт документы по названиям и текстам ссылок и по ним ищет обязательные; содержимое файлов не читается.</p><div class="panel table-wrap"><table><thead><tr><th>Документ</th><th>Состояние</th></tr></thead><tbody>${d.documents.map(x=>`<tr><td><a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${esc(x.label||x.text?.slice(0,180)||x.url.split('/').pop())} ↗</a><div class="state-info"><a href="${esc(x.source)}" target="_blank" rel="noopener noreferrer">Страница размещения</a></div></td><td>${esc(({read:'Текст извлечён',manual:'Нужна ручная проверка',error:'Ошибка чтения',external:'Внешний файл',robots:'Обход запрещён',deferred:'Не читался в этом режиме',listed:'Найден по названию; файл не открывался'})[x.state]||'Нет данных')}</td></tr>`).join('')||'<tr><td colspan="2">Документы не обнаружены в пределах обхода.</td></tr>'}</tbody></table></div>`}else if(state.reportTab==='evidence'){const order=['news','events','documents','schedule','contacts','about','structure','programs','employees','staff'];const evidencePages=[...d.pages].filter(p=>(!state.evidenceUrl||p.url.replace(/\/$/,'')===state.evidenceUrl.replace(/\/$/,''))&&(!state.evidenceQuery||(p.title+' '+p.url+' '+p.text).toLowerCase().includes(state.evidenceQuery.toLowerCase()))).sort((a,b)=>Math.min(...a.sections.map(s=>order.indexOf(s)).filter(i=>i>=0),99)-Math.min(...b.sections.map(s=>order.indexOf(s)).filter(i=>i>=0),99));content=`<h2>Полученные страницы</h2><div class="toolbar" style="padding:12px 0"><div class="search"><input id="evidence-search" type="search" aria-label="Поиск в доказательствах" placeholder="Найти страницу или фразу" value="${esc(state.evidenceQuery)}"></div>${state.evidenceUrl?'<button class="small" data-action="all-evidence">Все страницы</button>':`<span class="state-info">${evidencePages.length} страниц</span>`}</div><p class="muted">Снимки текста сохранены в этой проверке. Сайт по ссылке может измениться позднее.</p>${evidencePages.map(p=>`<details class="details" ${state.evidenceUrl?'open':''}><summary>${esc(p.title)} <span class="muted">· ${p.text.length.toLocaleString('ru-RU')} зн.</span><span class="evidence-path">${esc(new URL(p.url).pathname)}${p.fetched_at?' · '+date(p.fetched_at,true):''}</span></summary><p><a href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">${esc(p.url)} ↗</a></p><p>${esc(p.text.slice(0,14000))}</p></details>`).join('')||`<p>${d.pages.length?'По запросу ничего не найдено. Измените фразу поиска.':'Ни одна страница не получена.'}</p>`}${(d.news||[]).length?`<h2 style="margin-top:28px">Новости: даты публикации и события</h2><p class="muted">Дата события — по тексту новости (алгоритм audit) и, если включён ИИ, по ответу модели. При расхождении дата не используется для проверки срока 24 часа.</p><div class="panel table-wrap"><table><thead><tr><th>Новость</th><th>Опубликовано</th><th>Событие</th><th>Как установлено</th></tr></thead><tbody>${d.news.map(n=>`<tr><td><a href="${esc(n.url)}" target="_blank" rel="noopener noreferrer">${esc(n.title)} ↗</a>${(n.factcheck||[]).map(f=>`<div class="state-info">${esc(({confirmed:'Подтверждено',contradiction:'Расхождение',unverified:'Не подтверждено'})[f.status]||f.status)}: ${esc(f.claim)} — ${esc(f.note)}</div>`).join('')}</td><td class="nowrap">${date(n.published)}</td><td class="nowrap">${n.event_date?date(n.event_date):'—'}${n.delay_days!=null?`<div class="state-info">+${n.delay_days} дн.</div>`:''}</td><td>${esc(({algorithm:'Алгоритм',agreement:'Алгоритм и ИИ совпали',review:'Алгоритм и ИИ разошлись — нужна проверка',unknown:'Не установлена'})[n.event_date_status]||n.event_date_status)}${n.candidates&&n.event_date_status==='review'?`<div class="state-info">алгоритм: ${esc(n.candidates.algorithm||'—')} · ИИ: ${esc(n.candidates.model||'—')}</div>`:''}</td></tr>`).join('')}</tbody></table></div>`:''}<h2 style="margin-top:28px">Источники факт-чекинга</h2><p class="muted">${d.ai.state==='disabled'?'ИИ не использовался: работали офлайн-проверки дат audit (официальные праздники, юбилеи, дни недели).':d.ai.error?esc(d.ai.error):'Выводы модели требуют проверки инспектором: '+esc(d.ai.describe||d.ai.model||'')}</p>${(d.ai.sources||[]).map(s=>`<details class="details"><summary>${esc(s.title)}</summary><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">Внешний источник ↗</a><p>${esc(s.text)}</p></details>`).join('')}${(d.ai.search||[]).length?`<h3 style="margin-top:20px">Попытки поиска</h3>${d.ai.search.map(s=>`<p class="state-info">${esc(s.query||s.url)} · ${esc(({results:'Результаты получены',no_results:'Результаты не получены',unavailable:'Источник недоступен',robots:'Обход запрещён',deferred:'Не читался в этом режиме'})[s.status]||s.status)}${s.error?' · '+esc(s.error):''}</p>`).join('')}`:''}<h2 style="margin-top:28px">Ограничения и ошибки доступа</h2><ul class="notes-list">${d.limitations.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${d.errors.map(x=>`<details class="details"><summary>${esc(x.kind==='robots'?'Правила обхода':'Ошибка получения страницы')}</summary><p>${esc(x.url)}<br>${esc(x.error)}</p></details>`).join('')}`}else if(state.reportTab==='history'){content='<div id="history-list" class="loading">Загружаем историю…</div>';setTimeout(()=>loadHistory(d.organization.id),0)}
return `<a class="back" href="#reports">← Все проверки</a><div class="report-heading"><div class="eyebrow">ОТЧЁТ / ${kindName(d.organization.kind)}</div><h1>${esc(shortName(d.organization.name))}</h1><div class="report-meta"><a href="${esc(d.organization.url)}" target="_blank" rel="noopener noreferrer">${esc(new URL(d.organization.url).hostname)} ↗</a><span>${date(r.created,true)}</span><span>Получено ${d.pages.length} страниц</span>${badge(d.status,d.status==='unavailable'?'Нет доступа':d.status==='partial'?'Проверка неполная':'Отчёт сохранён')}<span>${modeName(d.mode)}</span></div><div class="mobile-summary">Охват <b>${pct(d.coverage)}</b> · Проверено ${counts.pass||0} пунктов · Нет данных ${counts.unknown||0}</div></div><div class="report-nav" role="tablist" aria-label="Разделы отчёта">${[['issues','Внимание',(counts.fail||0)+(counts.review||0)],['unknown','Нет данных',counts.unknown||0],['passed','Проверено',counts.pass||0],['documents','Документы',d.documents.length],['evidence','Доказательства',d.pages.length],['history','История','']].map(([key,label,n])=>`<button role="tab" aria-selected="${state.reportTab===key}" data-action="report-tab" data-tab="${key}" class="${state.reportTab===key?'selected':''}">${label} ${n!==''?`<span class="muted">${n}</span>`:''}</button>`).join('')}</div>${d.preliminary?`<div class="banner preliminary-banner"><div><b>Сайт проверен — идёт сверка между сайтами запуска</b><p>Эталон и одинаковые фото-заглушки сопоставляются после проверки всех сайтов; балл audit и выводы сравнения могут измениться.</p></div><button data-action="retry-route">Обновить отчёт</button></div>`:''}<div class="layout-two"><section>${content}</section><aside class="report-sidebar"><div class="info-panel"><div class="eyebrow">ПРОЗРАЧНОСТЬ ПРОВЕРКИ</div><div class="definition"><span>Подтверждённый охват</span><b style="font-size:26px">${pct(d.coverage)}</b><div class="scorebar" style="width:100%"><span style="width:${d.coverage||0}%"></span></div></div><div class="definition"><span>Оценка проверенных пунктов</span><b>${d.score==null?'—':d.score+' / 100'}</b></div><p>Оценка учитывает только подтверждённые пункты. Читайте её вместе с охватом.${d.coverage==null?' Охват и оценка не рассчитаны: нет подтверждённых данных.':''}</p>${d.audit_score!=null?`<div class="definition"><span>Балл audit (штрафы по критичности)</span><b>${d.audit_score} / 100</b><div class="state-info">${esc(d.audit_grade||'')}${d.is_reference?' · эталон своего типа':''}</div></div>`:''}${d.metrics?.total_seconds?`<div class="definition"><span>Время проверки</span><b>${d.metrics.total_seconds.toFixed(1)} с</b><div class="state-info">Загружено страниц: ${d.metrics.pages_fetched??'—'}</div></div>`:''}<div class="definition"><span>Смысловой анализ</span>${d.ai.state==='ok'?'Модель ответила'+(d.ai.news_checked?' · новостей: '+d.ai.news_checked:''):d.ai.state==='skipped'?'Модель не вызывалась: нет подходящих новостей':d.ai.state==='disabled'?'Модель не подключена':d.ai.state==='pending'?'Ожидает анализа':d.ai.state==='interrupted'?'Проверка остановлена':'Ошибка модели'}${d.ai.rejected?`<p>Отклонено выводов без точного основания: ${d.ai.rejected}.</p>`:''}</div><div class="actions" style="margin-top:20px"><a class="button primary" href="/api/reports/${r.id}/export/html" target="_blank" rel="noopener">Печать / PDF</a><a class="button" href="/api/reports/${r.id}/export/csv">CSV</a><a class="button small" href="/api/reports/${r.id}/export/json">Все данные JSON</a></div></div><details class="details"><summary>Полное наименование</summary><p>${esc(d.organization.name)}</p></details><p class="state-info">Исходный отчёт сохраняется неизменным. Решения инспектора хранятся отдельно.</p></aside></div>`}
async function loadHistory(id){try{const history=await api('/api/reports?org_id='+id);if(!$('#history-list'))return;$('#history-list').className='panel table-wrap';$('#history-list').innerHTML=`<table><thead><tr><th>Дата</th><th>Охват</th><th>Проблемы / к проверке</th><th></th></tr></thead><tbody>${history.map(x=>`<tr><td>${date(x.created,true)}</td><td>${pct(x.coverage)}</td><td>${x.issues} / ${x.review}</td><td><a href="#report/${x.id}">Открыть →</a></td></tr>`).join('')}</tbody></table>`}catch(e){toast(e.message,true)}}
function settingsView(){const s=state.data.settings;const num=v=>v==null?'':v;return `<div class="page-heading"><div><div class="eyebrow">ПАРАМЕТРЫ СЕРВИСА</div><h1>Настройки мониторинга</h1><p>Модель и параметры движка audit, автоматический запуск.</p></div></div><form id="settings-form"><div class="settings-grid"><aside class="settings-aside"><h3>ИИ-проверка новостей</h3><p>Модель audit определяет дату события в новости и выделяет проверяемые утверждения; с веб-поиском (Claude, Gemini через шлюз) — сверяет их с открытыми источниками. Без модели работают все правила audit, включая офлайн-сверку дат.</p><p>Пустые поля берутся из файла .env (AUDIT_LLM_*). Ключ остаётся на сервере приложения.</p></aside><section class="form-section"><div class="settings-block"><h2>Модель</h2><div class="toggle-row"><input type="checkbox" id="llm_enabled" name="llm_enabled" ${s.llm_enabled?'checked':''}><label for="llm_enabled">Использовать ИИ при полной проверке<small>Сейчас: ${esc(s.llm_effective||'—')}</small></label></div><div class="form-grid"><div class="field full"><label for="llm-preset">Быстрый выбор сервера</label><select id="llm-preset"><option value="custom">Свой сервер или значения из .env</option><option value="ollama" ${s.base_url.includes('11434')?'selected':''}>Ollama · localhost:11434</option><option value="lmstudio" ${s.base_url.includes('1234')?'selected':''}>LM Studio · localhost:1234</option></select></div><div class="field"><label for="llm_provider">Провайдер</label><select id="llm_provider" name="llm_provider"><option value="" ${s.llm_provider===''?'selected':''}>Из .env / авто</option><option value="openai" ${s.llm_provider==='openai'?'selected':''}>OpenAI-совместимый сервер</option><option value="anthropic" ${s.llm_provider==='anthropic'?'selected':''}>Anthropic API</option></select><small>Авто: OpenAI-совместимый, если указан адрес API.</small></div><div class="field"><label for="base_url">Адрес API</label><input name="base_url" id="base_url" type="url" value="${esc(s.base_url)}" placeholder="из .env, например http://localhost:11434/v1"><small>Включая /v1.</small></div><div class="field"><label for="api_key">API-ключ ${s.has_api_key?'· сохранён':''}</label><input id="api_key" name="api_key" type="password" autocomplete="new-password" placeholder="${s.has_api_key?'Оставьте пустым, чтобы сохранить':'Из .env или пусто для локального сервера'}"></div><div class="field"><label for="model">Модель</label><input id="model" name="model" value="${esc(s.model)}" list="model-list" placeholder="из .env"><datalist id="model-list"></datalist></div><div class="field"><label for="web_search">Веб-поиск</label><select id="web_search" name="web_search"><option value="" ${s.web_search===''?'selected':''}>Из .env / авто</option><option value="google" ${s.web_search==='google'?'selected':''}>Google Search (Gemini через шлюз)</option><option value="off" ${s.web_search==='off'?'selected':''}>Выключен</option></select></div><div class="field"><label for="json_mode">Режим JSON</label><select id="json_mode" name="json_mode"><option value="" ${s.json_mode===''?'selected':''}>Из .env (json_object)</option><option value="json_object" ${s.json_mode==='json_object'?'selected':''}>json_object</option><option value="json_schema" ${s.json_mode==='json_schema'?'selected':''}>json_schema</option><option value="off" ${s.json_mode==='off'?'selected':''}>Выключен</option></select></div><div class="field"><label for="llm_timeout">Таймаут модели, сек.</label><input type="number" id="llm_timeout" name="llm_timeout" min="5" max="1800" value="${num(s.llm_timeout)}" placeholder="из .env (120)"><small>Для локальных моделей на CPU — 300–600.</small></div><div class="field"><label for="llm_max_tokens">Лимит ответа, токенов</label><input type="number" id="llm_max_tokens" name="llm_max_tokens" min="256" max="64000" value="${num(s.llm_max_tokens)}" placeholder="из .env (4000)"></div><div class="field"><label for="reasoning_effort">reasoning_effort</label><input id="reasoning_effort" name="reasoning_effort" value="${esc(s.reasoning_effort)}" maxlength="20" placeholder="из .env; none — без рассуждений (Ollama)"></div><div class="field"><label for="llm_news">Новостей на сайт для ИИ</label><input type="number" id="llm_news" name="llm_news" min="0" max="15" value="${s.llm_news}"><small>Ответы кэшируются: повторная проверка той же новости не расходует запросы.</small></div></div><div class="actions" style="margin-top:20px"><button type="button" data-action="test-llm">Проверить подключение</button>${s.has_api_key?'<button class="text-button danger" type="button" data-action="clear-key">Удалить ключ</button>':''}</div><p class="state-info">Проверка отправляет одну тестовую новость (как <code>python -m audit llm-test</code>).</p><div id="llm-test-result" style="margin-top:14px"></div></div></section><aside class="settings-aside"><h3>Параметры обхода audit</h3><p>Те же параметры, что у <code>python -m audit run</code>. Все сайты Госвеба на одном сервере, поэтому общее число одновременных запросов ограничено.</p></aside><section class="form-section"><div class="form-grid"><div class="field"><label for="concurrency">Сайтов одновременно</label><input type="number" name="concurrency" id="concurrency" min="1" max="12" value="${s.concurrency}"></div><div class="field"><label for="http_concurrency">HTTP-запросов одновременно (всего)</label><input type="number" name="http_concurrency" id="http_concurrency" min="1" max="32" value="${s.http_concurrency}"></div><div class="field"><label for="timeout">Ожидание ответа сайта, сек.</label><input type="number" name="timeout" id="timeout" min="5" max="120" value="${s.timeout}"></div><div class="field"><label for="max_news">Новостей на сайт для проверки срока и фактов</label><input type="number" name="max_news" id="max_news" min="1" max="60" value="${s.max_news}"></div><div class="field"><label for="max_persons">Карточек сотрудников на раздел</label><input type="number" name="max_persons" id="max_persons" min="1" max="200" value="${s.max_persons}"></div><div class="field"><label for="cache_ttl">Срок кэша страниц, ч</label><input type="number" name="cache_ttl" id="cache_ttl" min="0" max="720" step="0.5" value="${s.cache_ttl}"></div></div><div class="toggle-row"><input type="checkbox" id="use_cache" name="use_cache" ${s.use_cache?'checked':''}><label for="use_cache">Использовать кэш страниц audit<small>Общий с CLI каталог .cache; повторная проверка в пределах срока не нагружает сайты.</small></label></div><div class="toggle-row"><input type="checkbox" id="image_hashes" name="image_hashes" ${s.image_hashes?'checked':''}><label for="image_hashes">Сравнивать фото сотрудников<small>Скачивает фото и ищет одинаковые картинки-заглушки на разных сайтах.</small></label></div><p class="notice" style="margin-top:20px">audit не выполняет JavaScript и не открывает файлы документов: документы распознаются по названиям. Визуальные требования памятки остаются ручной проверкой.</p></section><aside class="settings-aside"><h3>Автоматический запуск</h3><p>Проверяет все организации по расписанию. Приложение должно быть запущено; пропущенная проверка начнётся после его включения.</p></aside><section class="form-section"><div class="toggle-row" style="margin-top:0"><input type="checkbox" id="schedule_enabled" name="schedule_enabled" ${s.schedule_enabled?'checked':''}><label for="schedule_enabled">Проверять автоматически<small>Часовой пояс: Магадан, UTC+11.</small></label></div><div class="form-grid"><div class="field"><label for="schedule_interval_days">Интервал, дней</label><input type="number" name="schedule_interval_days" id="schedule_interval_days" min="1" max="30" value="${s.schedule_interval_days}"></div><div class="field"><label for="schedule_hour">Час запуска</label><select id="schedule_hour" name="schedule_hour">${Array.from({length:24},(_,i)=>`<option value="${i}" ${s.schedule_hour===i?'selected':''}>${String(i).padStart(2,'0')}:00</option>`).join('')}</select></div></div><p class="notice" style="margin-top:18px">${s.next_run?'Следующий запуск: '+date(s.next_run,true):'Расписание выключено. Новое время будет рассчитано при сохранении.'}</p></section></div><div class="sticky-actions"><span class="state-info">Параметры применятся к новым проверкам.</span><button type="submit" class="primary">Сохранить настройки</button></div></form>`}
function comparisonView(){return `<div class="page-heading"><div><div class="eyebrow">ПЕРЕКРЁСТНЫЙ КОНТРОЛЬ</div><h1>Сравнение с эталоном</h1><p>Сравниваем школы со школами, детские сады — с детскими садами.</p></div><a class="button" href="/api/export/summary.csv">Сводная таблица ↓</a></div><div class="banner"><div><b>Эталон — ориентир для проверки</b><p>Автоматический эталон — доступный сайт своего типа с наивысшим баллом audit (при равенстве — меньше критичных замечаний, больше документов и новостей). Категории документов — обязательные и дополнительные по правилам audit. Различия требуют проверки применимости.</p></div></div>${state.comparison.map(g=>`<section class="comparison-group panel"><div class="toolbar"><h2 style="margin:0">${g.kind==='school'?'Школы':'Детские сады'}</h2><span class="muted">Проверено ${g.rows.length}</span></div>${g.reference?`<div class="reference"><div class="eyebrow">${g.reference.manual?'ВЫБРАННЫЙ':'АВТОМАТИЧЕСКИЙ'} ЭТАЛОН</div><h3>${esc(g.reference.name)}</h3><p class="state-info">Проверка ${date(g.reference.created,true)} · <a href="#report/${g.reference.id}">Открыть основания →</a></p>${g.reference.categories.map(x=>`<span class="chip">${esc(x)}</span>`).join('')}</div>`:`<div class="reference"><h3>Эталон пока не выбран</h3><p class="state-info">Нужна проверка с достаточным охватом. Можно назначить сайт вручную после изучения отчёта.</p></div>`}${g.rows.length?`<div class="table-wrap"><table><thead><tr><th>Организация</th><th>Балл audit · охват</th><th>Документы</th><th>Не обнаружено относительно эталона</th><th></th></tr></thead><tbody>${g.rows.map(r=>`<tr><td><a href="#report/${r.id}" class="org-name">${esc(r.name)}</a><div class="state-info">${date(r.created)}</div></td><td>${r.audit_score??'—'} · ${pct(r.coverage)}</td><td>${r.documents}</td><td>${g.reference?(r.missing_compared_to_reference.length?r.missing_compared_to_reference.map(x=>`<span class="chip">${esc(x)}</span>`).join(''):'<span class="muted">Различий в распознанных категориях нет</span>'):'—'}</td><td><button class="small" data-action="set-reference" data-kind="${g.kind}" data-id="${r.org_id}" ${g.reference?.org_id===r.org_id?'disabled':''}>Назначить эталоном</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><p>После проверки здесь появится сравнение организаций.</p><a class="button" href="#registry">К реестру →</a></div>'}</section>`).join('')}<p class="state-info">Сравниваются последние сохранённые проверки. Документы группируются по названию и адресу; совпадение категории не подтверждает актуальность или юридическую полноту. Учреждения с разными функциями могут иметь разные перечни документов.</p>`}
function checklistView(){const rows=[["Новости: интервал до 14 дней", "Даты публикаций — из метаданных и подписей списка новостей (до 100 последних). Свежесть последней новости и интервалы за год; разрывы в летние каникулы отмечаются отдельно и мягче.", "Правила"], ["Новость в течение 24 часов после события", "Дата события извлекается из текста новости алгоритмом; при включённом ИИ — и моделью. Если они расходятся, дата не используется, вывод уходит инспектору.", "Правила + ИИ + инспектор"], ["Факт-чекинг", "Офлайн: даты государственных и памятных дней, юбилеи, соответствие дня недели дате. С ИИ и веб-поиском — сверка утверждений с открытыми источниками. Без источника вывод модели не засчитывается.", "Правила + ИИ"], ["Мероприятия: текущий и следующий квартал", "Даты мероприятий раздела сопоставляются с кварталами; прошедшие мероприятия ищутся среди новостей по датам и сходству названий.", "Правила"], ["Обязательные документы", "Перечень по Приказу Рособрнадзора № 1493: поиск по названиям документов, текстам ссылок подразделов «Сведений» и встроенному поиску сайта. Актуальность отчёта о самообследовании.", "Правила"], ["Педагогический состав и коллектив", "Карточки сотрудников: фото, уровень образования, контакты (детские сады). Одинаковые картинки у разных людей или на 3+ сайтах — заглушка.", "Правила + сверка сайтов"], ["Контакты, главная, ПОС", "Адрес, телефон, e-mail, режим работы, часы приёма; заголовки без значения. Для детских садов — контакты на главной. Баннер ПОС «Решаем вместе».", "Правила"], ["О школе, структура, расписание", "История и объём раздела «О школе», заполненность органов управления, модуль и файлы расписания, учебный год.", "Правила"], ["Программы и «Педагогам и сотрудникам»", "Элементы подраздела «Образование» и файлы программ; пустые подразделы раздела для педагогов.", "Правила"], ["Заглушки шаблона Госвеб", "Демо-тексты и подсказки редактора («Укажите…», «Примерно от … до … символов», Lorem ipsum) во всех полученных страницах.", "Правила"], ["Сравнение с эталоном", "Эталон своего типа — сайт с наивысшим баллом audit. Различия в дополнительных документах и разделах — ориентир для проверки.", "Сверка сайтов"], ["Визуальные требования памятки", "Качество фото, деловой стиль, шрифты, наложения блоков текстовым обходом не оцениваются — пункт всегда на ручной проверке.", "Инспектор"]];return `<div class="page-heading"><div><div class="eyebrow">ОСНОВАНИЯ ПРОВЕРКИ</div><h1>Что и как проверяем</h1><p>Проверки выполняет движок audit; интерфейс показывает их результаты и основания.</p></div></div><div class="layout-two"><section class="panel">${rows.map(([t,p,m],i)=>`<div class="checklist-row"><span class="number">${String(i+1).padStart(2,'0')}</span><div><h3>${t}</h3><p>${p}</p></div><span class="badge" style="white-space:normal;align-self:start">${m}</span></div>`).join('')}</section><aside class="info-panel"><h3>Четыре вида результата</h3><p>${badge('pass')}<br>Проверка audit выполнялась на данных сайта, замечаний нет. Отсутствие замечаний без выполненной проверки так не помечается.</p><p>${badge('fail')}<br>Замечание audit, подтверждённое правилом. Критичность — как в audit: критичная, высокая, средняя, низкая.</p><p>${badge('review')}<br>Нужно решение человека: сверка с эталоном, факт-чекинг, расхождение алгоритма и ИИ, визуальные требования, недоступность сайта.</p><p>${badge('unknown')}<br>Проверке не хватило данных или она не выполнилась. Не считается нарушением.</p><hr style="border:0;border-top:1px solid var(--line);margin:22px 0"><h3>Три показателя</h3><p><b>Охват</b> — доля пунктов с подтверждённым результатом. Не рассчитывается без данных.</p><p><b>Оценка</b> — доля успешных среди подтверждённых пунктов. Оценка 100 при малом охвате не означает, что сайт в порядке.</p><p><b>Балл audit</b> — 100 минус штрафы по критичности замечаний (с ограничением на раздел); по нему выбирается эталон.</p><a href="#settings">Настроить проверку →</a></aside></div>`}
function openModal(title,body,buttons){$('#modal-content').innerHTML=`<div class="modal-head"><h2 id="modal-title">${esc(title)}</h2><button class="close" data-action="close-modal" aria-label="Закрыть">×</button></div><div class="modal-body">${body}</div><div class="modal-footer">${buttons}</div>`;$('#modal').showModal()}
function newRun(ids){const orgs=state.data.organizations;const chosen=ids||[...state.selected];let body,targets;if(chosen.length){targets=chosen;body=`<p>Выбрано организаций: <b>${chosen.length}</b>.</p><p class="muted">Проверка затронет только выбранные сайты. Готовые отчёты сохранятся, даже если остановить запуск.</p><details class="details"><summary>Посмотреть список</summary><ul class="notes-list">${orgs.filter(o=>chosen.includes(o.id)).map(o=>`<li>${esc(o.name)}</li>`).join('')}</ul></details>`}else{targets=orgs.map(o=>o.id);body=`<div class="field"><label for="run-scope">Какие сайты проверить</label><select id="run-scope"><option value="all">Все организации · ${orgs.length}</option><option value="unverified">Только ещё не проверенные · ${orgs.filter(o=>!o.latest).length}</option><option value="school">Все школы · ${orgs.filter(o=>o.kind==='school').length}</option><option value="kindergarten">Все детские сады · ${orgs.filter(o=>o.kind==='kindergarten').length}</option></select><small>Поиск и фильтр реестра не меняют этот выбор.</small></div>`}body+=`<div class="mode-picker"><label class="mode-option"><input type="radio" name="run-mode" value="quick"><b>Быстрый обзор</b><span>До 5 свежих новостей и 10 карточек сотрудников на раздел. Без сравнения фото и без ИИ.</span></label><label class="mode-option"><input type="radio" name="run-mode" value="full" checked><b>Полная проверка</b><span>Все проверки audit с параметрами из настроек; ИИ-проверка новостей, если модель включена.</span></label></div><p class="notice" id="mode-summary" style="margin-top:20px">До ${state.data.settings.max_news} новостей и ${state.data.settings.max_persons} карточек сотрудников на раздел · ${state.data.settings.concurrency} сайтов одновременно.<br>${state.data.settings.llm_enabled?'ИИ: '+esc(state.data.settings.llm_effective)+'; не более '+state.data.settings.llm_news+' новостей на сайт.':'ИИ выключен: выполняются все правила audit без модели.'}</p><div id="run-error"></div>`;openModal('Новая проверка',body,`<button data-action="close-modal">Отмена</button><button class="primary" data-action="start-run" id="start-run-button">Начать проверку · ${targets.length}</button>`);$('#modal').runTargets=targets}
function settingsPayload(){const form=$('#settings-form');const fd=new FormData(form);const data={...state.data.settings};for(const k of ['has_api_key','next_run','llm_effective'])delete data[k];for(const name of ['llm_enabled','schedule_enabled','use_cache','image_hashes'])data[name]=form.elements[name].checked;for(const name of ['concurrency','http_concurrency','timeout','max_news','max_persons','cache_ttl','schedule_hour','schedule_interval_days','llm_news'])data[name]=Number(fd.get(name));for(const name of ['llm_timeout','llm_max_tokens']){const v=String(fd.get(name)||'').trim();data[name]=v?Number(v):null}for(const name of ['base_url','model','llm_provider','web_search','json_mode','reasoning_effort'])data[name]=String(fd.get(name)||'').trim();if(fd.get('api_key'))data.api_key=String(fd.get('api_key'));if(form.dataset.clearKey==='true')data.api_key='';return data}
document.addEventListener('click',async event=>{const b=event.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;try{
if(action==='retry-route'){state.report=null;await loadRoute()}
else if(action==='kind'){state.kind=b.dataset.kind;state.page=1;renderView()}
else if(action==='prev-page'||action==='next-page'){state.page+=action==='next-page'?1:-1;renderView();$('.toolbar')?.scrollIntoView({block:'start'})}
else if(action==='clear-selection'){state.selected.clear();renderView()}
else if(action==='close-modal')$('#modal').close();
else if(action==='new-run')newRun();
else if(action==='run-one')newRun([Number(b.dataset.id)]);
else if(action==='open-org'){const o=state.data.organizations.find(o=>o.id===Number(b.dataset.id));if(o.latest)location.hash='report/'+o.latest.id;else openModal(kindName(o.kind),`<h3>${esc(o.name)}</h3><p><a href="${esc(o.url)}" target="_blank" rel="noopener noreferrer">Открыть сайт ↗</a></p><p class="muted">Проверок ещё нет. Запустите первую, чтобы увидеть состояние разделов и рекомендации.</p>`,`<button data-action="close-modal">Закрыть</button><button class="primary" data-action="run-one" data-id="${o.id}" ${activeRun()?'disabled':''}>Проверить сайт</button>`)}
else if(action==='start-run'){const targets=$('#modal').runTargets;if(!targets?.length)throw new Error('В выбранной группе нет организаций');b.disabled=true;b.textContent='Запускаем…';try{await api('/api/runs',{method:'POST',body:JSON.stringify({organization_ids:targets,mode:document.querySelector('input[name="run-mode"]:checked')?.value||'full'})});$('#modal').close();state.selected.clear();await refresh();toast('Проверка запущена. Результаты появятся по мере готовности.')}finally{b.disabled=false;b.textContent='Начать проверку'}}
else if(action==='cancel-run'){b.disabled=true;await api('/api/runs/'+b.dataset.id+'/cancel',{method:'POST'});b.textContent='Останавливаем…';toast('Завершаем текущий запрос. Готовые отчёты сохранятся.')}
else if(action==='report-tab'){state.reportTab=b.dataset.tab;state.evidenceUrl='';renderView()}
else if(action==='saved-source'){state.reportTab='evidence';state.evidenceUrl=b.dataset.url;state.evidenceQuery='';renderView();$('.report-nav').scrollIntoView({block:'start'})}
else if(action==='all-evidence'){state.evidenceUrl='';state.evidenceQuery='';renderView()}
else if(action==='save-review'){const container=b.closest('[data-fingerprint]');const fingerprint=container.dataset.fingerprint;const data={state:container.querySelector('select').value,note:container.querySelector('input').value};await api('/api/reviews/'+fingerprint,{method:'PUT',body:JSON.stringify(data)});state.report.reviews[fingerprint]=data;toast('Решение инспектора сохранено')}
else if(action==='test-llm'){if(!$('#settings-form').reportValidity())return;b.disabled=true;b.textContent='Проверяем…';const result=$('#llm-test-result');result.innerHTML='<div class="notice">Ожидаем ответ модели…</div>';try{const d=await api('/api/llm/test',{method:'POST',body:JSON.stringify(settingsPayload())});result.innerHTML=`<div class="notice success">${esc(d.message)}<br>${esc(d.settings)}</div>`;$('#model-list').innerHTML=d.models.map(m=>`<option value="${esc(m)}"></option>`).join('');if(!$('#model').value)$('#model').value=d.model}catch(e){result.innerHTML=`<div class="notice error">${esc(e.message)}</div>`}finally{b.disabled=false;b.textContent='Проверить подключение'}}
else if(action==='clear-key'){$('#settings-form').dataset.clearKey='true';$('#api_key').value='';$('#api_key').placeholder='Ключ будет удалён при сохранении';toast('Сохраните настройки, чтобы удалить ключ')}
else if(action==='set-reference'){const cfg={...state.data.settings,['benchmark_'+b.dataset.kind]:Number(b.dataset.id)};delete cfg.has_api_key;delete cfg.next_run;state.data.settings=await api('/api/settings',{method:'PUT',body:JSON.stringify(cfg)});state.comparison=await api('/api/comparison');renderView();toast('Эталон назначен. Сравнение обновлено.')}
else if(action==='add-org'){openModal('Добавить организацию',`<form id="org-form"><div class="field"><label for="org-name">Название организации</label><input id="org-name" name="name" required minlength="3" maxlength="350" placeholder="Официальное название"></div><div class="field"><label for="org-url">Адрес сайта</label><input id="org-url" name="url" type="url" required placeholder="https://school.gosweb.gosuslugi.ru"></div><div class="field"><label for="org-kind">Тип учреждения</label><select id="org-kind" name="kind"><option value="school">Школа</option><option value="kindergarten">Детский сад</option></select></div><div id="org-error"></div></form>`,`<button data-action="close-modal">Отмена</button><button type="submit" form="org-form" class="primary">Добавить в реестр</button>`)}
}catch(e){toast(e.message,true);const error=$('#run-error');if(error)error.innerHTML=`<p class="notice error">${esc(e.message)}</p>`}});
document.addEventListener('input',event=>{if(event.target.id==='evidence-search'){const start=event.target.selectionStart;state.evidenceQuery=event.target.value;clearTimeout(queryTimer);queryTimer=setTimeout(()=>{renderView();const input=$('#evidence-search');input.focus();try{input.setSelectionRange(start,start)}catch{}},200)}else if(event.target.id==='registry-search'){clearTimeout(queryTimer);const start=event.target.selectionStart;state.query=event.target.value;state.page=1;queryTimer=setTimeout(()=>{renderView();const input=$('#registry-search');input.focus();try{input.setSelectionRange(start,start)}catch{}},200)}});
document.addEventListener('change',event=>{const el=event.target;if(el.dataset.select){const id=Number(el.dataset.select);el.checked?state.selected.add(id):state.selected.delete(id);renderView()}else if(el.id==='select-page'){const rows=state.data.organizations.filter(o=>(state.kind==='all'||o.kind===state.kind)&&(o.name+' '+o.url).toLowerCase().includes(state.query.toLowerCase())).slice((state.page-1)*state.perPage,state.page*state.perPage);for(const o of rows)el.checked?state.selected.add(o.id):state.selected.delete(o.id);renderView()}else if(el.id==='finding-filter'){state.findingFilter=el.value;renderView()}else if(el.id==='llm-preset'){if(el.value!=='custom'){$('#base_url').value=el.value==='ollama'?'http://localhost:11434/v1':'http://localhost:1234/v1';$('#llm_provider').value='openai';$('#web_search').value='off'}}else if(el.name==='run-mode'){const quick=el.value==='quick';const cfg=state.data.settings;$('#mode-summary').textContent=(quick?'До '+Math.min(cfg.max_news,5)+' новостей и '+Math.min(cfg.max_persons,10)+' карточек на раздел · без сравнения фото · без ИИ':'До '+cfg.max_news+' новостей и '+cfg.max_persons+' карточек на раздел'+(cfg.llm_enabled?' · ИИ: до '+cfg.llm_news+' новостей на сайт':' · без ИИ'))+' · '+cfg.concurrency+' сайтов одновременно.'}else if(el.id==='run-scope'){const orgs=state.data.organizations;const targets=orgs.filter(o=>el.value==='all'||el.value==='unverified'&&!o.latest||o.kind===el.value).map(o=>o.id);$('#modal').runTargets=targets;$('#start-run-button').textContent='Начать проверку · '+targets.length;$('#start-run-button').disabled=!targets.length}});
document.addEventListener('submit',async event=>{const form=event.target;if(!['org-form','settings-form'].includes(form.id))return;event.preventDefault();const b=event.submitter;b.disabled=true;try{if(form.id==='org-form'){await api('/api/organizations',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});$('#modal').close();await refresh();toast('Организация добавлена в реестр')}else{state.data.settings=await api('/api/settings',{method:'PUT',body:JSON.stringify(settingsPayload())});renderView();toast('Настройки сохранены')}}catch(e){toast(e.message,true);if($('#org-error'))$('#org-error').innerHTML=`<p class="notice error">${esc(e.message)}</p>`}finally{b.disabled=false}});
$('#modal').addEventListener('click',event=>{if(event.target===$('#modal')){const r=event.target.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)event.target.close()}});
window.addEventListener('hashchange',()=>loadRoute().catch(e=>toast(e.message,true)));
(async()=>{try{await refresh(false);await loadRoute();$('#view').classList.add('animate-in')}catch(e){$('#view').innerHTML=`<div class="empty"><h2>Сервис недоступен</h2><p>${esc(e.message)}</p><button onclick="location.reload()">Повторить</button></div>`}setInterval(async()=>{if(polling||document.hidden||$('#modal').open)return;polling=true;try{const previous=activeRun()?.id;await refresh(false);const current=activeRun();if(previous&&!current){toast('Проверка завершена. Отчёты сохранены.');if(state.route==='reports')state.reports=await api('/api/reports')}if(['registry','reports'].includes(state.route)&&!$('#registry-search')?.matches(':focus')){if(state.route==='reports')state.reports=await api('/api/reports');renderView()}}catch(e){console.warn('Не удалось обновить состояние',e)}finally{polling=false}},4000)})();
